def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:
    emb = self.item_emb(seq)
    emb = emb * torch.rsqrt(emb.square().mean(dim=-1, keepdim=True) + 1e-6)
    return emb.masked_fill(seq.eq(0).unsqueeze(-1), 0.0)

def encode(self, seq: torch.Tensor) -> torch.Tensor:
    emb = self.dropout(self.input_embeddings(seq))
